INSERT INTO public.jhb_content SELECT * FROM json_populate_recordset(null::public.jhb_content, E'[{"key":"hero","data":{"badge": "Next-Gen AI Automation Agency", "title": "Grow Your Business Online, Smarter and Faster With", "subtitle": "We help businesses of all sizes attract the right customers, build trust, and boost sales. With data-driven strategies, SEO, content, and digital solutions, we deliver the best digital marketing Salem—your growth is our mission every step of the way.", "highlight": "Best Digital Marketing Salem", "ctaPrimaryHref": "#contact", "ctaPrimaryLabel": "Contact Us", "ctaSecondaryHref": "#services", "ctaSecondaryLabel": "Explore Services"},"updated_at":"2026-06-10T12:00:00+00:00","updated_by":null}, 
