INSERT INTO public.jhb_home SELECT * FROM json_populate_recordset(null::public.jhb_home, E'[{"key":"draft","data":{"cta": {"title": "Ready to Digitalise Your Business?", "enabled": true, "textHtml": "<p>Get in touch and we will show you the fastest path to predictable, automated growth.</p>", "buttonHref": "#contact", "buttonText": "Contact Us"}, "hero": {"badge": "Next-Gen AI Automation Agency", "image": null, "title": " Smarter and Faster", "subtitle": "We help businesses of all sizes attract the right customers, build trust, and boost sales. With data-driven strategies, <a href=\\"https://www.youtube.com/\\">SEO,</a> content, and digital solutions, we deliver the best digital marketing Salem—your growth is our mission every step of the way.", "highlight": "Best Digital Marketing S", "buttonHref": "#contact", "buttonText": "Contact Us", "imageTitle": ""}, "about": {"image": null, "title": "We Build the Automated Future of Business", "enabled": true, "eyebrow": "Who We Are", "descriptionHtml": "<p>JHB Automations is a next-generation&nbsp;<span style=\\"font-size: 0.875rem;\\">. We help ambitious businesses automate their operations, generate leads on autopilot and scale faster — combining intelligent AI systems, high-performance web development and data-driven marketing.</span></p>"}, "founder": {"name": "Founder & CEO", "image": null, "company": "JHB Automations", "enabled": true, "eyebrow": "Founder Perspective", "heading": "Growth Depends on", "imageAlt": "Founder of JHB Automations", "highlight": "Predictable Systems", "focusTitle": "We Focus On", "focusPoints": ["Consistent Lead Flow", "Automated Customer Journeys", "Clear Messaging & Market Positioning", "Data-Driven Digital Systems"], "descriptionHtml": "<p>Growth depends on predictable systems, diversified lead channels, and automated workflows. Businesses that rely on a single source or manual operations limit their scalability. At JHB Automations, we help companies create multi-channel lead generation sy