INSERT INTO public.jhb_posts SELECT * FROM json_populate_recordset(null::public.jhb_posts, '[{"id":"2e372c96-f581-4426-a2ec-7098f306d142","slug":"ai-automation-tamil-nadu","title":"AI Automation for Businesses in Tamil Nadu","excerpt":"How local businesses across Tamil Nadu are using AI automation to cut manual work and scale faster.","content_html":"<p>Businesses across Tamil Nadu — from Salem to Chenni — are adopting AI automation to stay competitive. Here''s what''s driving the shift.</p><h2>From manual to automated</h2><p>Repetitive tasks like data entry, follow-ups and lead routing are now handled by intelligent workflows, freeing teams to focus on growth.</p><p>At JHB Automations, we help local companies design systems that reduce operational effort and increase revenue efficiency.</p>","cover_image":null,"category":"Business Automation","tags":["ai","tamil nadu","growth"],"author":"JHB Automations","status":"published","meta_title":"AI Automation in Tamil Nadu — JHB Automations","meta_description":"How businesses in Tamil Nadu use AI automation to reduce manual work and scale faster.","published_at":"2026-06-06T06:20:41.35894+00:00","created_at":"2026-06-12T06:20:41.35894+00:00","updated_at":"2026-06-12T06:20:41.35894+00:00","updated_by":null}, 
 {"id":"8bc37b37-240a-4f96-a380-c505de69f9c3","slug":"choosing-an-seo-specialist","title":"How to Choose the Right SEO Specialist","excerpt":"Not all SEO is equal. Here''s how to pick a partner who delivers sustainable, compounding organic growth.","content_html":"<p>SEO is a long game — and choosing the right specialist makes all the difference between wasted spend and compounding traffic.</p><h2>What to look for</h2><ul><li>Transparent reporting on rankings and traffic</li><li>Technical, on-page and authority-building expertise</li><li>A focus on revenue, not vanity metrics</li></ul><p>The best SEO partners build systems that keep paying off long after the work is done.</p>","cover_image":null,"category":"SEO","tags":["seo","strategy"],"author":"JHB Automations","status":"published","meta_title":"Choosing the Right SEO Specialist — JHB Automations","meta_description":"A practical guide to picking an SEO partner who delivers sustainable organic growth.","published_at":"2026-06-02T06:20:41.35894+00:00","created_at":"2026-06-12T06:20:41.35894+00:00","updated_at":"2026-06-12T06:20:41.35894+00:00","updated_by":null}, 
 {"id":"18a8ca17-d501-4639-885a-a28f360aca07","slug":"business-chat-automation-guide","title":"How Business Chat Automation Wins You More Customers","excerpt":"Discover how automating your WhatsApp and website chat captures every lead — even at 2 AM — and turns conversations into revenue.","content_html":"<p>Every missed message is a missed customer. In today''s always-on market, prospects expect instant replies — and businesses that make them wait lose the sale.</p><h2>Why chat automation matters</h2><p>AI-powered chat automation greets every visitor, answers common questions, qualifies leads and books meetings automatically. It works nights, weekends and holidays without adding headcount.</p><ul><li>Respond to every inquiry in seconds</li><li>Qualify and route hot leads to sales</li><li>Capture leads outside business hours</li></ul><h2>Getting started</h2><p>Start by mapping your most common customer questions, then deploy an assistant across your website and WhatsApp. The result: higher conversion from the traffic you already have.</p>","cover_image":"https://wzvzzcuennotfutklulh.supabase.co/storage/v1/object/public/jhb-media/1781593671521-ed5d55336a94087ec06a6c9306769cd9.jpg","category":"AI Automation","tags":["whatsapp","chatbot","leads"],"author":"JHB Automations","status":"published","meta_title":"Business Chat Automation Guide — JHB Automations","meta_description":"Learn how AI chat automation captures every lead 24/7 and converts conversations into revenue.","published_at":"2026-06-10T06:20:41.35894+00:00","created_at":"2026-06-12T06:20:41.35894+00:00","updated_at":"2026-06-16T07:08:23.048+00:00","updated_by":"b3fa86c2-511d-4383-b6ab-07c41ce0e8c8"}]');

