 {"id":"3695fd1e-9d47-43ef-aa4b-35dff6b03952","name":"Rahul Verma","role":"Marketing Head","company":"ShopSphere","quote":"Our organic traffic tripled in six months. The SEO and content engine they built keeps compounding every week.","rating":5,"photo_url":null,"sort_order":4,"active":true,"created_at":"2026-06-15T04:58:55.866696+00:00","updated_at":"2026-06-15T04:58:55.866696+00:00","updated_by":"b3fa86c2-511d-4383-b6ab-07c41ce0e8c8"}, 
